<style lang="scss" scoped src="./gms-save-custom-view-modal.scss"></style>

<script>
import {
  destroyModalRootContent,
  ensureModalRoot,
} from "../../util/ensure-modal-root";
import { Component, Prop, Vue } from "vue-property-decorator";
import Icon from "../icon/icon";
import { IconShape } from "../icon/icon.constants";
import Button from "../button/button";
import { ButtonMode, ButtonSize } from "../button/button.constants";
import Select from "../select/select";
import { MountingPortal } from "portal-vue";
import { SelectionMenuMode } from "../selection-menu/selection-menu.constants";
import TextInput from "../text-input/text-input.vue";
import { TextInputMode } from "../text-input/text-input.constants";

@Component({
  components: {
    Icon,
    Button,
    MountingPortal,
    Select,
    TextInput,
  },
})
export default class GmsSaveCustomViewModal extends Vue {
  @Prop({
    type: Array,
    default: () => [],
  })
  visibilityValues;

  @Prop({
    type: Boolean,
    default: false,
  })
  canOverwrite;

  @Prop({
    type: Object,
  })
  currentReport;

  page = 0;
  reportName = "";
  visibility = "";
  error = "";

  IconShape = IconShape;
  ButtonMode = ButtonMode;
  ButtonSize = ButtonSize;
  SelectionMenuMode = SelectionMenuMode;
  TextInputMode = TextInputMode;

  beforeMount() {
    destroyModalRootContent("Menu");
    this.modalRoot = ensureModalRoot();

    if (!this.modalRoot) {
      console.warn("Could not establish modal root for floating componentry");
      return;
    }

    window.addEventListener("resize", this.handleResize);
  }

  mounted() {
    // if we are coming from a canned report, or if we don't own
    // the report and can't overwrite, skip straight to the save as
    if (this.currentReport.type === "CANNED" || !this.canOverwrite) {
      this.page = 1;
    }
  }

  beforeDestroy() {
    window.removeEventListener("resize", this.handleResize);
  }

  handleResize() {
    this.$forceUpdate();
  }

  get modalRootId() {
    return `#${this.modalRoot.id}`;
  }

  get containerStyle() {
    return {
      height: `${window.innerHeight}px`,
    };
  }

  handleSaveReport() {
    // reset error state
    this.error = null;

    // TODO - validate for uniqueness
    if (this.reportName === "") {
      this.error = "Please input a name";
    }

    if (this.visibility === "") {
      this.error = "Please select a visibility";
    }

    if (this.error) {
      return;
    }

    const reportInfo = {
      name: this.reportName,
      visibility: this.visibility,
    };

    /**
     * Emits when the user clicks Save as a New Report
     *
     * @event saveNewReport
     */
    this.$emit("saveNewReport", reportInfo);
  }

  handleSelectVisibility(value) {
    this.visibility = value;
  }

  handleCloseOutside(e) {
    if (e.target !== this.$refs.container) return;
    this.handleClose();
    e.stopPropagation();
    e.preventDefault();
  }

  handleClose() {
    /**
     * Emits when the user closes the modal
     *
     * @event close
     */
    this.$emit("close");
  }

  handleSaveOverCurrentReport() {
    const reportInfo = {
      name: this.reportName,
      visibility: this.visibility,
    };
    /**
     * Emits when the user clicks Save Over Current Report button
     *
     * @event saveOverCurrentReport
     */
    this.$emit("saveOverCurrentReport", reportInfo);
  }

  handleSaveNewReport() {
    // They chose to overwrite/create a new report
    // Navigate to page 2 to set a name and visibility
    this.page = 1;
  }
}
</script>

<template>
  <MountingPortal :mountTo="modalRootId" append>
    <div
      class="GmsSaveCustomViewModal"
      :style="containerStyle"
      ref="container"
      @click="handleCloseOutside"
    >
      <div class="GmsSaveCustomViewModal__Content">
        <div class="GmsSaveCustomViewModal__Header">
          <div class="GmsSaveCustomViewModal__Title">
            <h2>Save your Custom View</h2>
            <h3 v-if="error">{{ error }}</h3>
          </div>
          <div class="GmsSaveCustomViewModal__Quit" @click="handleClose">
            <Icon :shape="IconShape.CLOSE" :size="14.25" :color="'#65667780'" />
          </div>
        </div>
        <div class="GmsSaveCustomViewModal__Lower">
          <template v-if="page == 0">
            <div class="GmsSaveCustomViewModal__Lower">
              <div class="GmsSaveCustomViewModal__Instruction">
                <h1>
                  Would you like to save your changes to
                  <span>{{ currentReport.label }}</span
                  >?
                </h1>
                <h2>You can also save this edit as a new report.</h2>
              </div>
              <div class="GmsSaveCustomViewModal__SaveOptions">
                <Button
                  class="GmsSaveCustomViewModal__LeftButton"
                  label="Save Over Current Report"
                  :mode="ButtonMode.PRIMARY"
                  :size="ButtonSize.SMALL"
                  @click="handleSaveOverCurrentReport"
                />
                <Button
                  label="Save as a New Report"
                  :mode="ButtonMode.SUBTLE"
                  :size="ButtonSize.SMALL"
                  @click="handleSaveNewReport"
                />
              </div>
            </div>
          </template>
          <template v-if="page == 1">
            <div class="GmsSaveCustomViewModal__Message">
              You’ve made edits to this report. To save your custom report, give
              it a new name.
              <span v-if="!canOverwrite"
                >This edit will be saved as a new report.</span
              >
            </div>
            <div class="GmsSaveCustomViewModal__Form">
              <div class="GmsSaveCustomViewModal__Report">
                <div class="GmsSaveCustomViewModal__SubTitle">
                  {{ "Report Title" }}
                </div>
                <TextInput
                  placeholder="New Custom Report"
                  :mode="TextInputMode.GMS_SAVE"
                  v-model="reportName"
                />
              </div>
              <div class="GmsSaveCustomViewModal__Visibility">
                <div class="GmsSaveCustomViewModal__SubTitle">
                  {{ "Visiblility" }}
                </div>
                <Select
                  label="Select Visibility"
                  :value="visibility"
                  :items="visibilityValues"
                  @select="handleSelectVisibility"
                />
              </div>
            </div>
            <div class="GmsSaveCustomViewModal__Buttons">
              <Button
                class="GmsSaveCustomViewModal__LeftButton"
                label="Cancel"
                :mode="ButtonMode.SUBTLE"
                :size="ButtonSize.SMALL"
                @click="handleClose"
              />
              <Button
                label="Save Report"
                :mode="ButtonMode.PRIMARY"
                :size="ButtonSize.SMALL"
                @click="handleSaveReport"
              />
            </div>
          </template>
        </div>
      </div>
    </div>
  </MountingPortal>
</template>
